    """
    Dehydrate a ``datetime.time`` object to a serializable representation.

    If ``value`` is ``None``, ``None`` is returned.  
    If ``value`` is not a :class:`datetime.time` instance, a ``TypeError`` is raised.

    The function returns the ISO 8601 formatted string representation of the time,
    e.g. ``"14:30:00"``.  Time-zone information is included if present.

    :param value: The time value to dehydrate.
    :type value: datetime.time
    :return: ISO 8601 string representation of the time or ``None``.
    :rtype: str | None
    """
    # Allow None to propagate
    if value is None:
        return None

    # Validate type
    try:
        # ``datetime.time`` is usually available in the global namespace during runtime
        if not isinstance(value, datetime.time):
            raise TypeError(f"dehydrate_time expects datetime.time, got {type(value).__name__}")
    except NameError:
        # In case ``datetime`` is not imported, fall back to attribute check
        if not hasattr(value, "isoformat") or not hasattr(value, "hour"):
            raise TypeError(f"dehydrate_time expects datetime.time, got {type(value).__name__}")

    # Convert to ISO format string
    try:
        return value.isoformat()
    except Exception as exc:
        raise TypeError(f"Could not dehydrate time value: {exc}") from exc

