        if len(value) == 2:
            try:
                return (float(value[0]), float(value[1]))
            except (TypeError, ValueError):
                pass

    # Mapping with keys 'x' and 'y'
    if isinstance(value, dict):
        if "x" in value and "y" in value:
            try:
                return (float(value["x"]), float(value["y"]))
