def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""
    # Validate name
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    # Validate fields
    if not isinstance(fields, (list, tuple)):
        raise TypeError(f"fields must be a list or tuple, got {type(fields).__name__}")
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"Each field name must be a string, got {type(f).__name__}")
        if f in field_names:
            raise ValueError(f"Duplicate field name: {f}")
        field_names.append(f)
    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")
    # Class attributes
    attrs = {}
    attrs['__doc__'] = f"{name} dynamically generated from fields: {field_names}"
    attrs['srid_map'] = srid_map
    # Define initializer
    def __init__(self, *args, **kwargs):
        # Assign positional arguments to fields
        for i, value in enumerate(args):
            if i < len(field_names):
                setattr(self, field_names[i], value)
        # Assign keyword arguments
        for key, value in kwargs.items():
            if key in field_names:
                setattr(self, key, value)
            else:
                raise AttributeError(f"{name} has no field named {key}")
        # Set unspecified fields to None
        for fn in field_names:
            if not hasattr(self, fn):
                setattr(self, fn, None)
    attrs['__init__'] = __init__
    # Determine base class
    base = globals().get('Point', object)
    # Create and return the new class
    return type(name, (base,), attrs)

