                    raise
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
            return result
        # Copy metadata
        wrapper.__name__ = wrapper_name
        wrapper.__doc__ = wrapper_doc
        return wrapper
    return decorator

