def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        raise TypeError("classes must be an iterable of class objects")
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects")
    minimal = []
    for cls in iterator:
        if not isinstance(cls, type):
            raise TypeError(f"Expected class objects, got {type(cls).__name__}")
        # Skip if this cls is already a subclass of a kept base
        skip = False
        for kept in minimal:
            try:
                if issubclass(cls, kept):
                    skip = True
                    break
            except TypeError:
                raise TypeError(f"Failed issubclass check between {cls} and {kept}")
        if skip:
            continue
        # Remove any kept bases that are subclasses of this new cls
        minimal = [b for b in minimal if not issubclass(b, cls)]
        minimal.append(cls)
    return minimal

