def to_csv(self, separator=",", header=None):
    """
    Convert the graph's points to a CSV-formatted string.

    Parameters
    ----------
    separator : str, optional
        Delimiter used to separate values. Defaults to ",".
    header : str, optional
        A string added as the first line of the CSV output when provided.

    Returns
    -------
    str
        The CSV representation of the graph's points.

    Notes
    -----
    Each point is expected to be a tuple-like object where the first
    element is the coordinate (which may itself be an iterable) and the
    second element is the value (which may also be an iterable).  The
    coordinate and value are converted to strings, separated by
    ``separator``.  Iterables are flattened and joined using the same
    separator.  Strings are treated as scalars and are not split.
    """
    lines = []

    if header is not None:
        lines.append(str(header))

    # If the graph is iterable we can loop over it; otherwise we try to
    # expose an attribute that might hold points.
    try:
        iterator = iter(self)
    except TypeError:
        # Attempt to find a common container of points
        if hasattr(self, "points"):
            iterator = iter(self.points)
        else:
            raise ValueError("Object is not iterable and has no 'points' attribute")

    for idx, point in enumerate(iterator):
        try:
            # If point is a two-element sequence, treat as (coord, value)
            if hasattr(point, "__getitem__") and len(point) == 2:
                coord, value = point
            else:
                # Treat the entire point as the coordinate; value is None
                coord = point
                value = None
        except Exception:
            # Fallback for any unexpected structure
            coord = point
            value = None

        # Process coordinate
        try:
            # Coerce to string unless it's an iterable
            if isinstance(coord, str):
                coord_str = coord
            elif hasattr(coord, "__iter__") and not isinstance(coord, (bytes, bytearray)):
                coord_str = separator.join(str(c) for c in coord)
            else:
                coord_str = str(coord)
        except Exception:
            coord_str = str(coord)

        # Process value
        if value is None:
            value_str = ""
        else:
            try:
                if isinstance(value, str):
                    value_str = value
                elif hasattr(value, "__iter__") and not isinstance(value, (bytes, bytearray)):
                    value_str = separator.join(str(v) for v in value)
                else:
                    value_str = str(value)
            except Exception:
                value_str = str(value)

        # Combine and add to lines
        line = f"{coord_str}{separator}{value_str}" if value_str != "" else f"{coord_str}"
        lines.append(line)

    return "\n".join(lines)

