    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    # Ensure key is a string
    if not isinstance(key, str):
        raise ValidationError("Key must be a string.")
    # Key must not be empty
    if not key:
        raise ValidationError("Key cannot be empty.")
    # Define allowed characters: letters, digits, underscore, hyphen
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
    # The first character must be a letter or underscore
    if key[0] not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_":
        raise ValidationError(
            "Key must start with a letter or underscore."
        )
    # Check each character
    for ch in key:
        if ch not in allowed:
            raise ValidationError(
                f"Invalid character '{ch}' in key."
            )

