    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    The identifying fields are considered to be ``apiVersion`` and ``kind`` at the
    top level and ``metadata.name`` and ``metadata.namespace`` within the metadata block.
    """
    # Use a helper to safely handle recursive construction
    def _recursively_process(d, is_first_level):
        if not isinstance(d, dict):
            # Not a dict: replace with None
            return None

        result = {}
        for key, value in d.items():
            # Determine whether we should copy the value or set to None
            copy_value = None

            # Identify special handling for the first level
            if is_first_level:
                if key in ("apiVersion", "kind"):
                    copy_value = value
                elif key == "metadata":
                    # Process the metadata sub-dictionary separately
                    if isinstance(value, dict):
                        meta_res = {}
                        for m_key, m_val in value.items():
                            if m_key in ("name", "namespace"):
                                meta_res[m_key] = m_val
                            else:
                                # Any other metadata field gets None (or a recursive call)
                                if isinstance(m_val, dict):
                                    meta_res[m_key] = _recursively_process(m_val, False)
                                else:
                                    meta_res[m_key] = None
                        copy_value = meta_res
                    else:
                        copy_value = None

            # If copy_value wasn't set by first-level logic, decide based on type
            if copy_value is None:
                if isinstance(value, dict):
                    copy_value = _recursively_process(value, False)
                elif isinstance(value, list):
                    # Keep lists as None; specific handling is done in the list helper
                    copy_value = None
                else:
                    copy_value = None

            result[key] = copy_value

        return result

    try:
        return _recursively_process(manifest_dict, first_level)
    except Exception:
        # In case of any unexpected errors, fall back to an empty schema
        return {}

