def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema``.
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    import copy

    # Basic validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest)}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema)}"
        )
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response)}")

    # Ensure the last_applied_manifest has at least the same length as response
    # Fill missing indices with None
    while len(last_applied_manifest) < len(response):
        last_applied_manifest.append(None)

    for idx, rsp_item in enumerate(response):
        # If the observer_schema indicates no field to observe at this index, skip
        if idx < len(observer_schema) and observer_schema[idx] is None:
            continue

        # Update or create the item in last_applied_manifest
        if idx >= len(last_applied_manifest) or last_applied_manifest[idx] is None:
            # Deep copy to avoid shared references
            last_applied_manifest[idx] = copy.deepcopy(rsp_item)
        else:
            # Recursively update nested structures
            if isinstance(rsp_item, dict) and isinstance(last_applied_manifest[idx], dict):
                # Import the dict updater if available
                try:
                    from . import update_last_applied_manifest_dict_from_resp
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], observer_schema[idx], rsp_item
                    )
                except Exception:
                    # If dict updater not available, override
                    last_applied_manifest[idx] = copy.deepcopy(rsp_item)
            elif isinstance(rsp_item, list) and isinstance(last_applied_manifest[idx], list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], observer_schema[idx], rsp_item
                )
            else:
                # For other types, simply replace if different
                if last_applied_manifest[idx] != rsp_item:
                    last_applied_manifest[idx] = copy.deepcopy(rsp_item)

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`,
    this function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema`` describing the desired
            shape of the data.
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    for idx, schema_item in enumerate(observer_schema):
        # Get the corresponding response item if it exists
        resp_item = response[idx] if idx < len(response) else None

        # Expand the target list if necessary
        if idx >= len(last_applied_manifest):
            # We don't know the exact type; if the schema says it's a dict we
            # initialize with an empty dict, otherwise ``None``.
            if isinstance(schema_item, dict):
                last_applied_manifest.append({})
            else:
                last_applied_manifest.append(None)

        target = last_applied_manifest[idx]

        # Handle nested lists
        if isinstance(schema_item, list):
            # Ensure the target element is a list
            if not isinstance(target, list):
                target = []
                last_applied_manifest[idx] = target

            # If we have a response list, process each expected element
            if isinstance(resp_item, list):
                # Make sure the target is at least as long as the response,
                # filling with defaults based on the schema
                for _ in range(len(resp_item) - len(target)):
                    sub_schema = schema_item[0] if schema_item else None
                    target.append(
                        {} if isinstance(sub_schema, dict) else None
                    )

                for j, sub_schema in enumerate(schema_item):
                    sub_resp = resp_item[j] if j < len(resp_item) else None

                    sub_target = (
                        target[j]
                        if j < len(target)
                        else (
                            {}
                            if isinstance(sub_schema, dict)
                            else None
                        )
                    )
                    if isinstance(sub_schema, dict):
                        if not isinstance(sub_target, dict):
                            sub_target = {}
                            if j < len(target):
                                target[j] = sub_target
                            else:
                                target.append(sub_target)
                        try:
                            update_last_applied_manifest_dict_from_resp(
                                sub_target, sub_schema, sub_resp
                            )
                        except Exception:
                            pass
                    else:
                        if sub_resp is not None:
                            if j < len(target):
                                target[j] = sub_resp
                            else:
                                target.append(sub_resp)
            continue

        # Handle dictionary schema
        if isinstance(schema_item, dict):
            # Ensure the target is a dictionary
            if not isinstance(target, dict):
                target = {}
                last_applied_manifest[idx] = target

            if resp_item is not None and isinstance(resp_item, dict):
                try:
                    update_last_applied_manifest_dict_from_resp(
                        target, schema_item, resp_item
                    )
                except Exception:
                    pass
            continue

        # Primitive value: set directly if a response value is available
        if resp_item is not None:
            last_applied_manifest[idx] = resp_item

    return last_applied_manifest

