def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has the required attributes
    if not hasattr(app, "spec"):
        raise ValueError("The application object does not have a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("The application spec does not contain 'manifest'.")

    # Ensure the observer_schema dictionary exists
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        # create empty dict if missing
        try:
            app.spec.observer_schema = {}
        except Exception as e:
            raise ValueError("Unable to initialize 'observer_schema' on the application spec.") from e

    # Iterate over all resources in the manifest
    manifest_items = app.spec.manifest
    # The manifest can be a list or a mapping of resources
    if isinstance(manifest_items, dict):
        # If the manifest is a mapping keyed by resource name, extract its values
        manifest_items = manifest_items.values()
    elif not isinstance(manifest_items, list):
        # If it is neither list nor dict, skip processing gracefully
        return app.spec.observer_schema

    for resource in manifest_items:
        if not isinstance(resource, dict):
            # Skip any non-dict entries, they cannot represent a k8s resource
            continue

        kind = resource.get("kind")
        if not kind:
            # Skip resources w/o a kind field (not a standard k8s resource)
            continue

        # If a custom observer schema is already defined, skip this resource
        if kind in app.spec.observer_schema:
            continue

        # Build a minimal default observer schema using the standard fields
        default_schema = {}
        for field in ("apiVersion", "kind", "metadata", "spec"):
            if field in resource:
                default_schema[field] = resource[field]

        # Store the default schema under the resource kind.  If the kind already
        # exists but the schema is empty, overwrite it to ensure some structure
        app.spec.observer_schema[kind] = default_schema if default_schema else {}

    return app.spec.observer_schema

