            # Fall back to the instance's spec_version if available
            extracted_version = getattr(self, "spec_version", None)

    # Determine which spec version to use for further validation
    spec_version = extracted_version if extracted_version is not None else getattr(self, "spec_version", None)
    if spec_version is None:
