    try:
        digests_needed = set(digests_used)
    except TypeError:
        # In case digests_used contains unhashable items
        digests_needed = set()
        for d in digests_used:
            try:
                digests_needed.add(d)
            except TypeError:
                # Non-hashable element; skip or handle as needed
                pass

    # Gather all digests from manifest_files
    present_digests = set()
    for mf in manifest_files:
        if isinstance(mf, dict):
            # Common container image manifest: may have 'digests' list/tuple/set
            if 'digests' in mf:
                try:
                    dig_list = mf['digests']
                except Exception:
