def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory or zip file directory. If empty,
        file names are returned as given.
    xmls : list of str
        List of XML file paths (absolute or relative).
    files : list of str
        List of file paths in the folder or zipfile.

    Returns
    -------
    dict
        key: name of the XML base (without extension)
        value: list of file paths that share this base name
    """
    # Basic input validation
    if not isinstance(source, str):
        raise TypeError("source must be a string")
    if not isinstance(xmls, (list, tuple)):
        raise TypeError("xmls must be a list or tuple of strings")
    if not isinstance(files, (list, tuple)):
        raise TypeError("files must be a list or tuple of strings")
    for xml in xmls:
        if not isinstance(xml, str):
            raise TypeError("xmls must contain strings")
    for f in files:
        if not isinstance(f, str):
            raise TypeError("files must contain strings")

    def _basename(path):
        """Return the file name component of a path, handling both '/' and '\\' separators."""
        if not path:
            return ""
        # Split on both path separators
        parts = path.replace("\\", "/").split("/")
        return parts[-1]

    def _strip_ext(name):
        """Return the name without the last extension."""
        if "." in name:
            return name.rsplit(".", 1)[0]
        return name

    def _join(path, rel):
        """Join source with rel, ensuring a single separator."""
        if not path:
            return rel
        if rel.startswith(path):
            return rel
        return path.rstrip("/") + "/" + rel

    result = {}
    try:
        for xml_path in xmls:
            xml_file_name = _basename(xml_path)
            base_name = _strip_ext(xml_file_name)
            matched_files = []
            for f in files:
                file_name = _basename(f)
                if file_name == xml_file_name or file_name.startswith(base_name):
                    matched_files.append(_join(source, f))
            result[base_name] = matched_files
    except Exception as exc:
        raise RuntimeError(f"Failed to group files by XML basename: {exc}") from exc

    return result

