def add_asset(self, basename, file_path):
    """
    Registers an asset with a given basename and file_path.
    The asset is added to an internal dictionary `self._assets`.
    If the asset already exists, a ValueError is raised.
    If the file_path does not point to an existing file, a FileNotFoundError is raised.
    """
    # Validate input types
    if not isinstance(basename, str):
        raise TypeError(f"basename must be a string, got {type(basename).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"file_path must be a string, got {type(file_path).__name__}")

    # Check file existence if the path refers to an actual file
    # Use os.path.isfile; assume os module is available in the surrounding context
    try:
        import os
    except ImportError:
        os = None
    if os is not None and not os.path.isfile(file_path):
        raise FileNotFoundError(f"The file at '{file_path}' does not exist")

    # Ensure the internal asset storage exists
    if not hasattr(self, "_assets") or not isinstance(self._assets, dict):
        self._assets = {}

    # Check for duplicate keys
    if basename in self._assets:
        raise ValueError(f"An asset with basename '{basename}' already exists")

    # Store the asset
    self._assets[basename] = file_path

    # Optionally return nothing
    return None

