        if not isinstance(xpath_expr, str):
            continue  # ignora valores não string para evitar colisões
        try:
            # Tenta obter uma lista de resultados
            results = node.xpath(xpath_expr)
            if results:
                # Se o resultado for string (ex.: xpath apontando a um nó de texto)
                if isinstance(results[0], str):
                    return results[0].strip()
