def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    The representation is indented according to the `indent` level.
    If `debug` is True, type information is included for each value.
    """
    # Validate arguments
    try:
        indent = int(indent)
        debug = bool(debug)
    except Exception:
        # Fallback to simple string representation if args are invalid
        return str(self)

    # Keep track of objects already seen to avoid infinite recursion
    seen = set()

    def _render(obj, level):
        """
        Recursive helper to format an object.
        """
        # Handle self-referential objects
        obj_id = id(obj)
        if obj_id in seen:
            return f"<{obj.__class__.__name__} ... (circular)>"
        seen.add(obj_id)

        # If the object itself implements pretty, delegate to it
        if hasattr(obj, "pretty") and callable(getattr(obj, "pretty")):
            try:
                return obj.pretty(level, debug=debug)
            except Exception:
                # Fall back to repr if pretty fails
                return repr(obj)

        # Simple types
        if isinstance(obj, (int, float, complex, str, bool, type(None))):
            return repr(obj)

        # Containers: list, tuple, set, frozenset
        if isinstance(obj, (list, tuple, set, frozenset)):
            items = []
            for idx, item in enumerate(obj):
                rendered_item = _render(item, level + 4)
                items.append(" " * level + f"{idx}: {rendered_item}")
            closing_indent = " " * (level if level > 0 else 0)
            return (
                f"{type(obj).__name__}["
                + "\n".join(items)
                + "\n"
                + closing_indent
                + "]"
            )

