        except Exception:
            pass

        try:
            # Absorption for OR: A | (A & B)
            if _is_or(expr):
                a, b = expr.args
                if _is_and(b):
                    if a == b.args[0] or a == b.args[1]:
                        return a
                # Negative absorption: A | (~A & B) = A | B
                if _is_and(b):
