    carry = {a: 0 for a in attrs}

    for attr in attrs:
        val = getattr(self, attr, 0)
        if val is None:
            val = 0
        if isinstance(val, (int,)):
            args[attr] = val
        else:
            # Handle float values (or int subclass)
            try:
                val_float = float(val)
            except Exception:
                # If conversion fails, treat as zero
                val_float = 0.0
            int_part = int(val_float)
            frac_part = val_float - int_part
