        carry['hours'] = 0
    if carry['minutes']:
        args['seconds'] = args.get('seconds', 0) + int(carry['minutes'] * 60)
        carry['minutes'] = 0
    if carry['seconds']:
        args['microseconds'] = args.get('microseconds', 0) + int(carry['seconds'] * 1_000_000)
        carry['seconds'] = 0
    if carry['milliseconds']:
        args['microseconds'] = args.get('microseconds', 0) + int(carry['milliseconds'] * 1_000)
        carry['milliseconds'] = 0
    # Any remaining carry is absorbed into microseconds
    if carry['microseconds']:
        args['microseconds'] = args.get('microseconds', 0) + int(carry['microseconds'])
        carry['microseconds'] = 0

