        keys = ["major", "minor", "patch", "pre", "build"]
        d = {}
        for i, key in enumerate(keys):
            if i < len(seq):
                d[key] = seq[i]
            else:
                d[key] = None
        return d

    # Helper to normalise a mapping (case‑insensitive keys)
    def _dict_from_mapping(di):
        normalized = {}
        for k, v in di.items():
