def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : iterable or mapping
        The version components. For an iterable, the order defines the
        component positions. For a mapping, keys are used in formatted
        strings.
    style : str or callable
        How to combine the pieces.  Accepted values:

        * ``"dot"`` or ``"."``    – join pieces with '.'.
        * ``"dash"`` or ``"-"``   – join pieces with '-'.
        * ``"space"`` or ``" "``  – join pieces with a single space.
        * A format string containing ``{`` or ``%`` – e.g. ``"{major}.{minor}.{patch}"`` or ``"%d.%d.%d"``.
        * A callable – will be called with the pieces (``callable(*pieces)`` or
          ``callable(**pieces)`` depending on whether *pieces* is iterable or
          mapping).

    Returns
    -------
    str
        The formatted version string.

    Raises
    ------
    TypeError
        If ``pieces`` is not iterable/mapable or if ``style`` is neither
        a string nor a callable.
    ValueError
        If formatting fails or ``style`` is an unsupported string.
    """
    if not callable(style) and not isinstance(style, str):
        raise TypeError("style must be a string or callable")

    # Handle mapping (dict-like)
    is_mapping = isinstance(pieces, dict)
    pieces_list = list(pieces) if not is_mapping else None

    try:
        # Callable style
        if callable(style):
            if is_mapping:
                return str(style(**pieces))
            return str(style(*pieces_list))

        # String style
        s = style.strip()
        # Simple delimiters
        if s in {"dot", "."}:
            return ".".join(str(p) for p in pieces_list)
        if s in {"dash", "-"}:
            return "-".join(str(p) for p in pieces_list)
        if s in {"space", " "}:
            return " ".join(str(p) for p in pieces_list)

        # Format string with {} placeholders
        if "{" in s:
            if is_mapping:
                return s.format(**pieces)
            return s.format(*pieces_list)

        # Format string with % placeholders
        if s.startswith(("%", "%(")):
            return s % tuple(pieces_list)

        # Treat the string itself as a delimiter
        return s.join(str(p) for p in pieces_list)

    except Exception as exc:
        raise ValueError(f"Failed to render pieces with style '{style}': {exc}") from exc

