def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Find the root objects to validate
    try:
        root = getattr(self, "root", None)
    except Exception:
        root = None

    if root is None:
        return 0, 0

    # Use a stack for iterative depth–first traversal
    objects_to_process = [root]
    num_objects = 0
    good_objects = 0

    while objects_to_process:
        obj = objects_to_process.pop()
        num_objects += 1
        is_good = True

        # Validation
        if validate_objects:
            try:
                validate_fn = getattr(obj, "validate", None)
                if callable(validate_fn):
                    if not validate_fn():
                        is_good = False
                        if show_warnings:
                            print(f"Validation failed for object {obj!r}")
                else:
                    # No validate method, assume it passes
                    pass
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Exception during validation of {obj!r}: {exc}")

        # Digest check
        if check_digests:
            try:
                if hasattr(obj, "digest") and hasattr(obj, "compute_digest"):
                    digest_val = getattr(obj, "compute_digest")()
                    if digest_val != getattr(obj, "digest"):
                        is_good = False
                        if show_warnings:
                            print(f"Digest mismatch for object {obj!r}")
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Exception during digest check of {obj!r}: {exc}")

        if is_good:
            good_objects += 1

        # Add children to the stack if any
        try:
            children = getattr(obj, "children", None)
            if children:
                if isinstance(children, (list, tuple)):
                    objects_to_process.extend(children)
                else:
                    # Assume it’s an iterable
                    objects_to_process.extend(list(children))
        except Exception:
            # If accessing children fails, skip
            pass

    return num_objects, good_objects

