def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        The method checks each object stored in ``self`` under the attribute
        ``objects`` – this attribute may be a list, a tuple, or a dictionary
        containing objects.  For each object the following is performed:

        * If ``validate_objects`` is True and the object implements a
          ``validate`` method or an ``is_valid`` property, that method/property
          is called and the returned boolean determines whether the object is
          considered valid.
        * If ``check_digests`` is True and the object implements a
          ``check_digest`` method, that method is called and the returned
          boolean at splits the object into *good* or *bad* according to the
          result.
        * Any exception raised from the validation or digest check marks the
          object as invalid.
        * If ``show_warnings`` is True a warning is printed for every object
          that fails validation or digest checks.

        Parameters
        ----------
        validate_objects : bool, optional
            Whether to perform object-level validation.  Default is True.
        check_digests : bool, optional
            Whether to perform a digest check on each object.  Default is True.
        show_warnings : bool, optional
            Whether to print warnings for invalid objects.  Default is False.

        Returns
        -------
        tuple[int, int]
            The number of objects inspected and the number of objects that
            passed the validation checks.
        """
        # Validate input flags
        if not isinstance(validate_objects, bool):
            raise ValueError("validate_objects must be a boolean")
        if not isinstance(check_digests, bool):
            raise ValueError("check_digests must be a boolean")
        if not isinstance(show_warnings, bool):
            raise ValueError("show_warnings must be a boolean")

        # Attempt to collect objects from the instance
        if hasattr(self, "objects"):
            raw = self.objects
        else:
            # Fallback: nothing to validate
            return 0, 0

        # Normalise to a sequence of objects
        if isinstance(raw, dict):
            objects = list(raw.values())
        elif isinstance(raw, (list, tuple, set)):
            objects = list(raw)
        else:
            # If objects is a single object, treat it as a list with that element
            objects = [raw]

        num_objects = 0
        good_objects = 0

        for obj in objects:
            num_objects += 1
            good = True

            # Object-level validation
            if validate_objects:
                try:
                    if callable(getattr(obj, "validate", None)):
                        result = obj.validate()
                        if not result:
                            good = False
                    elif hasattr(obj, "is_valid"):
                        is_valid = getattr(obj, "is_valid")
                        if isinstance(is_valid, bool):
                            if not is_valid:
                                good = False
                        elif callable(is_valid):
                            if not is_valid():
                                good = False
                        else:
                            # Unexpected type; consider invalid
                            good = False
                except Exception:
                    good = False

            # Digest check
            if check_digests and good:
                try:
                    if callable(getattr(obj, "check_digest", None)):
                        digest_ok = obj.check_digest()
                        if not digest_ok:
                            good = False
                except Exception:
                    good = False

            if good:
                good_objects += 1
            elif show_warnings:
                try:
                    name = getattr(obj, "name", repr(obj))
                except Exception:
                    name = repr(obj)
                print(f"Warning: Object {name} failed validation or digest check.")

        return num_objects, good_objects

