    """Create and initialize a new OCFL storage root."""
    if not hasattr(self, "storage_root"):
        raise AttributeError("The instance must have a 'storage_root' attribute.")
    root = self.storage_root
    if isinstance(root, str):
        root_path = root
    else:
        try:
            root_path = str(root)
        except Exception as exc:
            raise ValueError("storage_root must be convertible to a string path") from exc

    try:
        if not os.path.isdir(root_path):
            os.makedirs(root_path, exist_ok=True)
        # Create the minimal OCFL directory structure
        ocfl_dir = os.path.join(root_path, ".ocfl")
        objects_dir = os.path.join(ocfl_dir, "objects")
        os.makedirs(objects_dir, exist_ok=True)
        # Create a placeholder manifest file if it doesn't exist
        manifest_path = os.path.join(ocfl_dir, "manifest.ocfl")
        if not os.path.exists(manifest_path):
            with open(manifest_path, "w", encoding="utf-8") as f:
                f.write("# OCFL Manifest\n")
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize OCFL root '{root_path}': {exc}") from exc
    self.initialized = True

