def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input type
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of version directory names.")
    # Ensure root inventory is present and a dictionary
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("Instance must have a 'root_inventory' dictionary attribute.")
    # Prepare container for differences
    self._different_digests = {}
    # Process each version directory in order
    for ver in version_dirs:
        if not isinstance(ver, str):
            raise TypeError(f"Version directory names must be strings, got {type(ver)}.")
        # Attempt to retrieve the inventory for this version
        inventory = None
        # First look for a direct attribute named inventory_<ver>
        attr_name = f"inventory_{ver}"
        if hasattr(self, attr_name):
            inventory = getattr(self, attr_name)
        # If not found, look inside an inventories dict
        if inventory is None and hasattr(self, "inventories") and isinstance(self.inventories, dict):
            inventory = self.inventories.get(ver)
        # If still None, raise an error
        if inventory is None:
            raise FileNotFoundError(f"Inventory for version '{ver}' not found.")
        # Inventory must be a mapping of content ids to digests
        if not isinstance(inventory, dict):
            raise TypeError(f"Inventory for version '{ver}' must be a dict.")
        # Record differences for this version
        self._different_digests[ver] = {}
        # Check each entry in the inventory
        for content_id, digest in inventory.items():
            if not isinstance(content_id, str):
                raise TypeError(f"Content ID must be a string in inventory for version '{ver}'.")
            if not isinstance(digest, str):
                raise TypeError(f"Digest must be a string for content '{content_id}' in version '{ver}'.")
            root_digest = self.root_inventory.get(content_id)
            if root_digest is None:
                # New content not present in root inventory
                self._different_digests[ver][content_id] = {
                    "status": "missing_in_root",
                    "inventory_digest": digest,
                }
            elif digest != root_digest:
                # Digest differs from root
                self._different_digests[ver][content_id] = {
                    "status": "mismatch",
                    "root_digest": root_digest,
                    "inventory_digest": digest,
                }
        # Check for items present in root but missing in the inventory
        missing_in_inventory = set(self.root_inventory) - set(inventory)
        for missing_id in missing_in_inventory:
            self._different_digests[ver][missing_id] = {
                "status": "missing_in_inventory",
                "root_digest": self.root_inventory[missing_id],
            }
    # No explicit return value necessary; results are stored on the instance.

