def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("No version directories supplied")

    base_dir = getattr(self, "base_dir", None)
    if not base_dir:
        raise ValueError("self.base_dir attribute not set")

    root_inv_path = os.path.join(base_dir, "inventory.json")
    if not os.path.isfile(root_inv_path):
        raise ValueError(f"Root inventory file missing at {root_inv_path}")

    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except Exception as e:
        raise ValueError(f"Failed to load root inventory: {e}") from e

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a dict mapping path to digest")

    cumulative_entries = {}
    inventory_differences = {}

    for version_dir in version_dirs:
        inv_path = os.path.join(base_dir, version_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise ValueError(f"Inventory file missing for version '{version_dir}' at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                current_inv = json.load(f)
        except Exception as e:
            raise ValueError(f"Failed to load inventory for '{version_dir}': {e}") from e

        if not isinstance(current_inv, dict):
            raise ValueError(f"Inventory for '{version_dir}' must be a dict mapping path to digest")

        # Ensure all previously seen entries are present with identical digests
        for path, expected_digest in cumulative_entries.items():
            if path not in current_inv or current_inv[path] != expected_digest:
                raise ValueError(f"Inventory for '{version_dir}' missing or mismatched entry '{path}' "
                                 f"from a previous version")

        # Update cumulative set of entries
        cumulative_entries.update(current_inv)

        # Gather entries whose digest differs from the root inventory
        diff_paths = [p for p, d in current_inv.items()
                      if root_inventory.get(p) is not None and root_inventory[p] != d]
        if diff_paths:
            inventory_differences[version_dir] = diff_paths

    # Store differences for later checks (attribute name is chosen for clarity)
    setattr(self, "inventory_differences", inventory_differences)
    return inventory_differences

