            # Trim spaces and remove duplicated commas
            cleaned = ','.join(part.strip() for part in ids.split(',') if part.strip())
            return cleaned or None
        if isinstance(ids, (list, tuple)):
            cleaned_parts = []
            for part in ids:
                if part is None:
                    continue
                if isinstance(part, (int, float)):
                    cleaned_parts.append(str(part))
                elif isinstance(part, str):
                    # split in case strings contain commas
                    cleaned_parts.extend(
                        p.strip() for p in part.split(',') if p.strip()
                    )
                else:
                    # Unsupported type inside list
                    raise ValueError(f"Unsupported type in bug_ids list: {type(part).__name__}")
            return ','.join(cleaned_parts) or None
        raise ValueError(f"Unsupported type for bug_ids: {type(ids).__name__}")

