            map1 = {k.value: (k, val) for k, val in v1.value}
            map2 = {k.value: (k, val) for k, val in v2.value}

            merged_entries = []
            processed = set()

            # Preserve order: iterate over first mapping's entries
            for k_node, v_node in v1.value:
                k_val = k_node.value
                if k_val in map2:
                    merged_val = merge_node(map2[k_val][1], v_node)
                    merged_entries.append((k_node, merged_val))
