def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Ensure we don't modify the original arguments
    args = list(unparsed_arguments)
    namespaces = {}
    claimed_indices = set()

    # Precompute value to indices mapping for efficient lookup
    val_to_all_indices = {}
    for idx, val in enumerate(args):
        val_to_all_indices.setdefault(val, []).append(idx)

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(args)
        except Exception:
            # In case of parsing error, skip parsing for this subparser
            # Use defaults only and treat all args as remaining
            namespace = parser.parse_args([])
            remaining = args
        namespaces[name] = namespace

        # Determine which indices were claimed by this parser
        # Map each remaining value to an index that it consumes
        used_indices = set()
        for val in remaining:
            # Find an unused index for this value
            for idx in val_to_all_indices.get(val, []):
                if idx not in used_indices:
                    used_indices.add(idx)
                    break

        # All indices not used in remaining are claimed by this parser
        claimed = set(range(len(args))) - used_indices
        claimed_indices.update(claimed)

    # Remaining arguments not claimed by any subparser
    remaining_args = [arg for idx, arg in enumerate(args) if idx not in claimed_indices]

    return namespaces, remaining_args

