def addignored(ignored):
    """
    Return a comma-separated string of ignored file names from the current git repository.
    If the `ignored` parameter is provided, it acts as a filter: only those ignored files
    that are present in the supplied collection will be returned. The output list is sorted.
    """
    # Normalize the ignored input into a set of filenames
    if isinstance(ignored, str):
        ignored_set = {item.strip() for item in ignored.split(',') if item.strip()}
    else:
        try:
            ignored_set = set(ignored)
        except Exception:
            ignored_set = set()

    try:
        # Run git command to get ignored files
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        # Git command failed or not installed
        return ''

    # Split the output into a list, strip whitespace, and filter non-empty lines
    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]

    # Apply filter if ignored_set was provided
    if ignored_set:
        files = [f for f in files if f in ignored_set]

    # Sort the final list
    files.sort()

    return ','.join(files)

