    """
    Checks if the host is the localhost.

    Accepts a hostname or IP address string and returns True if it resolves to a loopback address.
    Handles both IPv4 and IPv6 loopback addresses ("127.0.0.1" / "127.0.0.0/8" and "::1").
    For special host names like "localhost", it returns True directly.
    If the host cannot be parsed or resolved, the function returns False.
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # 1. Quick check for the canonical name
    if host.lower() == "localhost":
        return True

    # Remove optional port and IPv6 zone identifiers
    # Handles patterns like "127.0.0.1:80", "[::1]:80", "fe80::1%lo0"
    addr = host
    if ':' in addr:
        if addr.startswith('[') and addr.endswith(']'):
            # IPv6 literal in brackets, remove them
            addr = addr[1:-1]
        if '%' in addr:
            # IPv6 zone idx, discard it
            addr = addr.split('%', 1)[0]
        if ':' not in addr:  # colon now only indicates IPv4 port separator
            # likely a port was appended
            addr = addr.split(':', 1)[0]

