def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    try:
        if script is None:
            return ""
        if not isinstance(script, str):
            raise TypeError("script must be a string")
        # split into lines, strip whitespace, ignore empty lines
        lines = script.splitlines()
        cleaned = [line.strip() for line in lines if line.strip()]
        return seperator.join(cleaned)
    except Exception as exc:
        # log or re-raise as needed; here we simply re-raise for clarity
        raise exc from None

