def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise ValueError("Matcher cannot be None.")

    # Initialize name and default as None
    name = None
    default = None

    # Try to handle a regex match object
    if isinstance(matcher, (bytes, bytearray)):
        # Bytes objects are not expected; convert for safety
        try:
            matcher = matcher.decode()
        except Exception:
            matcher = str(matcher)

    # Regex match objects have group methods
    if hasattr(matcher, "group"):
        try:
            name = matcher.group(1)
        except Exception:
            # group(1) might be missing, fallback to group('name')
            try:
                name = matcher.group('name')
            except Exception:
                name = None
        try:
            default = matcher.group(2)
        except Exception:
            # Maybe named group 'default'
            try:
                default = matcher.group('default')
            except Exception:
                default = None

    # If matcher is iterable (like list or tuple) with two elements
    elif hasattr(matcher, "__iter__") and not isinstance(matcher, (str, bytes)):
        # Avoid treating string-like iterables as iterables
        try:
            # Convert to list to enforce two elements
            parts = list(matcher)
            if len(parts) >= 1:
                name = parts[0]
            if len(parts) >= 2:
                default = parts[1]
        except Exception:
            pass

    # If matcher is a dict with known keys
    elif isinstance(matcher, dict):
        name = matcher.get("name") or matcher.get("var") or matcher.get("key") or matcher.get("env") or matcher.get("environment")
        default = matcher.get("default")

    # If still no name, try treating matcher as a simple string
    if name is None:
        # Try : separated format
        try:
            s = str(matcher)
            if ":" in s:
                name_part, default_part = s.split(":", 1)
                name = name_part.strip()
                default = default_part.strip()
            else:
                name = s.strip()
        except Exception:
            raise ValueError("Unable to extract environment variable name from matcher.")

    if not isinstance(name, str) or not name:
        raise ValueError("Environment variable name must be a non-empty string.")

    # Resolve the value from environment
    env_value = os.environ.get(name)
    if env_value is not None:
        return env_value

    if default is not None:
        return default

    raise KeyError(f"Environment variable '{name}' is not set and no default value provided.")

