def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    # Validate input type
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Failed to parse image_href: {e}")

    # Scheme and netloc are required
    if not parsed.scheme:
        raise ValueError("image_href must contain a URL scheme")
    if not parsed.netloc:
        raise ValueError("image_href must contain a network location (hostname)")

    # Remove leading slash from path to get image_id
    image_id = parsed.path.lstrip('/')
    if not image_id:
        raise ValueError("image_href must contain a non-empty path as image ID")

    # Determine whether SSL is used (only for https)
    use_ssl = parsed.scheme.lower() == 'https'

    return (image_id, parsed.netloc, use_ssl)

