def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("The 'commands' argument must not be None.")
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("The 'args' argument must be a list or tuple.")
    # Ensure all args are strings
    args = [str(a) for a in args]
    # Build the command
    if isinstance(commands, str):
        cmd_str = commands.strip()
        if args:
            cmd_full = f"{cmd_str} {' '.join(args)}"
        else:
            cmd_full = cmd_str
        cmd = cmd_full
        use_shell = True
    else:
        if not isinstance(commands, (list, tuple)):
            raise TypeError("The 'commands' argument must be a string, list, or tuple.")
        cmd = list(commands) + list(args)
        use_shell = False
    if verbose:
        if isinstance(cmd, list):
            print("Executing command:", ' '.join(cmd))
        else:
            print("Executing command:", cmd)
    # Set up stderr handling
    stderr_opt = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            shell=use_shell,
            stdout=subprocess.PIPE,
            stderr=stderr_opt,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        msg = f"Command '{cmd}' failed with return code {e.returncode}."
        raise RuntimeError(msg) from e
    except OSError as e:
        raise RuntimeError(f"Execution failed: {e}") from e
    return result.stdout

