                    msg=f"Environment resolution error in {filename}: {e}",
                    args=(),
                    exc_info=(type(e), e, e.__traceback__)
                )
                error_records.append(record)
                continue

        # Apply overrides if any
        if overrides:
            if not isinstance(overrides, dict):
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Overrides provided for {filename} is not a dict",
                    args=(),
                    exc_info=None
                )
