def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple of:
        - dict mapping configuration filename to its parsed configuration object
        - sequence of logging.LogRecord instances containing any parse errors
    """
    import logging
    import os
    import json
    import re
    try:
        import yaml
    except Exception:
        yaml = None

    logger = logging.getLogger(__name__)
    configurations = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                # Try JSON first if extension indicates .json
                if filename.lower().endswith('.json'):
                    data = json.load(f)
                else:
                    if yaml is None:
                        raise ImportError("PyYAML is required for non-JSON configuration files")
                    # Load YAML safely
                    data = yaml.safe_load(f)
        except Exception as exc:
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to load '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        if not isinstance(data, dict):
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Configuration in '{filename}' is not a dictionary (found {type(data).__name__})",
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply overrides if provided
        if overrides and filename in overrides:
            override_dict = overrides[filename]
            if isinstance(override_dict, dict):
                data.update(override_dict)
            else:
                record = logger.makeRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    fn=filename,
                    lno=0,
                    msg=f"Override for '{filename}' is not a dictionary (found {type(override_dict).__name__})",
                    args=(),
                    exc_info=None
                )
                error_records.append(record)

        # Resolve environment variable placeholders if requested
        if resolve_env:
            env_pattern = re.compile(r'\$\{([^}]+)\}')

            def _resolve(value):
                if isinstance(value, str):
                    def repl(match):
                        return os.getenv(match.group(1), match.group(0))
                    return env_pattern.sub(repl, value)
                elif isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_resolve(v) for v in value]
                return value

            try:
                data = _resolve(data)
            except Exception as exc:
                record = logger.makeRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    fn=filename,
                    lno=0,
                    msg=f"Failed to resolve environment variables in '{filename}': {exc}",
                    args=(),
                    exc_info=None
                )
                error_records.append(record)

        configurations[filename] = data

    return configurations, error_records

