def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        from zope.interface import Invalid
    except Exception:
        # Fallback in case zope.interface isn't importable; this will raise later
        Invalid = Exception

    errors = []

    # ------------------------------------------------------------------
    # 1. Check that the candidate claims to provide the interface.
    # ------------------------------------------------------------------
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(Invalid(
                    f"Candidate {candidate!r} does not provide interface {iface!r}"))
        except Exception as e:
            errors.append(Invalid(f"Error checking providedBy: {e}"))

    # ------------------------------------------------------------------
    # 2. Check that all interface methods are defined by the candidate.
    # ------------------------------------------------------------------
    # The interface may expose its methods via _methods or methods attributes.
    interface_methods = getattr(iface, "_methods", None)
    if interface_methods is None:
        # A fallback: use .methods() if present
        try:
            interface_methods = {k: v for k, v in iface._interfaceMethods().items()}
        except Exception:
            interface_methods = {}
    for name, iface_method in interface_methods.items():
        if not hasattr(candidate, name):
            errors.append(Invalid(f"Missing method {name!r} required by interface"))
            continue

        # Compare signatures if both are inspectable
        try:
            import inspect
            interface_sig = getattr(iface_method, "__signature__", None)
            candidate_attr = getattr(candidate, name)
            # candidate may be a function, bound method, or descriptor
            if inspect.isfunction(candidate_attr) or inspect.ismethod(candidate_attr):
                candidate_sig = inspect.signature(candidate_attr)
            else:
                # For descriptors, attempt to fetch the function
                desc_func = getattr(candidate_attr, "__func__", None)
                if desc_func and inspect.isfunction(desc_func):
                    candidate_sig = inspect.signature(desc_func)
                else:
                    candidate_sig = None
            if interface_sig is not None and candidate_sig is not None:
                # signature objects may not be directly comparable; compare commonly
                if interface_sig != candidate_sig:
                    errors.append(Invalid(
                        f"Signature mismatch for method {name!r}: "
                        f"expected {interface_sig}, got {candidate_sig}"))
        except Exception as e:
            # On failure to inspect, we cannot guarantee signature correctness.
            errors.append(Invalid(f"Error inspecting signature for {name!r}: {e}"))

    # ------------------------------------------------------------------
    # 3. Check that all interface attributes are defined.
    # ------------------------------------------------------------------
    interface_attrs = getattr(iface, "_attributes", None)
    if interface_attrs is None:
        # Attempt fallback via iface._interfaceAttributes()
        try:
            interface_attrs = {k: v for k, v in iface._interfaceAttributes().items()}
        except Exception:
            interface_attrs = {}
    for name in interface_attrs:
        if not hasattr(candidate, name):
            errors.append(Invalid(f"Missing attribute {name!r} required by interface"))

    # ------------------------------------------------------------------
    # 4. Raise collected errors or return True when none.
    # ------------------------------------------------------------------
    if errors:
        # If only a single error, raise it directly as per historic behaviour.
        if len(errors) == 1:
            raise errors[0]
        # Multiple errors: aggregate and raise one Invalid with details.
        aggregated_msg = "\n".join(str(e) for e in errors)
        raise Invalid(aggregated_msg)

    return True

