def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not bases:
        return type
    # If an explicit metaclass is provided, use it if it is a type
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit_metaclass must be a type, got {type(explicit_mc)!r}")
        return explicit_mc

    # Gather metaclasses of all bases
    metaclasses = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base must be a class (type), got {type(base)!r}")
        metaclasses.add(base.__class__)

    # If all bases share the same metaclass, use that
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Find the most derived metaclass that is a subclass of all others
    most_derived = None
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            if most_derived is None or issubclass(mc, most_derived):
                most_derived = mc

    if most_derived is not None:
        return most_derived

    # Fallback: return type
    return type

