def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime instance and returns
    an ISO‑8601 string with a trailing "Z" to indicate UTC.
    If the input datetime is timezone‐aware it is converted to UTC.
    Raises TypeError for non‑datetime inputs.
    """
    if dt is None:
        return None

    # We expect a datetime instance
    if not hasattr(dt, "strftime"):
        raise TypeError(f"input must be a datetime instance, got {type(dt)!r}")

    # If the datetime has timezone info, convert it to UTC
    try:
        offset = dt.utcoffset()
        if offset and offset.total_seconds() != 0:
            dt = dt - offset
    except Exception:
        # If utcoffset is not available or fails, leave dt unchanged
        pass

    try:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as exc:
        raise ValueError("Failed to format datetime") from exc

