def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.

    The expected format is an ISO 8601 UTC timestamp with seconds precision and
    a trailing ``Z`` (e.g. ``2023-05-01T13:45:30Z``).  ``dt`` may be a
    :class:`datetime.datetime`, :class:`datetime.date`, a numeric timestamp
    (seconds since the epoch) or a non‑empty string that can be parsed by
    :func:`datetime.datetime.fromisoformat`.  Any other input type will
    raise :class:`TypeError`.  ``None`` is also considered an error.

    The time zone is coerced to UTC; naive datetimes are treated as UTC.
    Microseconds are truncated.
    """
    import datetime

    # Validate input
    if dt is None:
        raise TypeError("dt must not be None")

    # Convert input to a datetime object
    if isinstance(dt, datetime.datetime):
        dt_obj = dt
    elif isinstance(dt, datetime.date):
        dt_obj = datetime.datetime(dt.year, dt.month, dt.day)
    elif isinstance(dt, (int, float)):
        try:
            dt_obj = datetime.datetime.fromtimestamp(dt, tz=datetime.timezone.utc)
        except Exception as exc:
            raise TypeError("timestamp must be a valid int or float") from exc
    elif isinstance(dt, str):
        try:
            # Try ISO format first
            dt_obj = datetime.datetime.fromisoformat(dt)
        except ValueError:
            # Fallback: try common delimiters
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    dt_obj = datetime.datetime.strptime(dt, fmt)
                    break
                except Exception:
                    continue
            else:
                raise TypeError("string dt is not a recognized datetime format")
    else:
        raise TypeError(f"Unsupported type for dt: {type(dt).__name__}")

    # Ensure datetime is timezone aware (UTC)
    if dt_obj.tzinfo is None:
        dt_obj = dt_obj.replace(tzinfo=datetime.timezone.utc)
    else:
        dt_obj = dt_obj.astimezone(datetime.timezone.utc)

    # Truncate microseconds
    dt_obj = dt_obj.replace(microsecond=0)

    iso_str = dt_obj.isoformat()
    # Replace UTC offset with trailing Z
    if iso_str.endswith("+00:00"):
        iso_str = iso_str[:-6] + "Z"
    return iso_str

