def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in one or more directories.

    Parameters
    ----------
    settings_dirs : str or iterable of str
        Directory or directories to search. If a single string is provided,
        it is treated as one directory. Nonexistent directories are ignored.
    spec_option : str or iterable of str, optional
        Pattern(s) to filter files. Supports glob-style wildcards
        (e.g. "*.txt", "**/*.py"). If ``None`` is passed, all files are
        returned. Non-string values in the iterable are ignored.

    Returns
    -------
    list of str
        Sorted list of absolute file paths that match the given patterns
        within the specified directories.

    Raises
    ------
    TypeError
        If ``settings_dirs`` is not a string or an iterable of strings.
        If ``spec_option`` is not ``None`` and not a string or an iterable
        of strings.
    """
    from pathlib import Path

    # Normalize settings_dirs to a list of directory paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError as exc:
            raise TypeError(
                "settings_dirs must be a string or an iterable of strings"
            ) from exc

    # Normalize spec_option to a list of patterns
    if spec_option is None:
        patterns = ["*"]
    else:
        if isinstance(spec_option, (str, bytes)):
            patterns = [spec_option]
        else:
            try:
                # Filter out non-string elements
                patterns = [p for p in spec_option if isinstance(p, (str, bytes))]
                if not patterns:
                    patterns = ["*"]
            except TypeError as exc:
                raise TypeError(
                    "spec_option must be None, a string, or an iterable of strings"
                ) from exc

    results = []

    for dir_path in dirs:
        if not isinstance(dir_path, (str, bytes)):
            continue  # Skip invalid directory entries
        base = Path(dir_path)
        if not base.is_dir():
            continue
        for pattern in patterns:
            # Use glob which supports '**' for recursive patterns
            try:
                for candidate in base.glob(pattern):
                    if candidate.is_file():
                        # Convert to absolute path for consistency
                        try:
                            resolved = candidate.resolve(strict=True)
                        except FileNotFoundError:
                            resolved = candidate.absolute()
                        results.append(str(resolved))
            except Exception:
                # Skip patterns that raise unexpected errors
                continue

    return sorted(set(results))

