def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
                      Each argument should contain a value and an associated
                      maximum allowed length. `args` can be a dict whose
                      values are either:
                      * a tuple/list of the form (value, max_len)
                      * a dict with keys 'value' and 'max_len' or 'max_length'
                      Additionally, `args` can be an iterable of such tuples,
                      where the iteration index is used as the argument name.
        """
        if not args:
            return

        # Determine iteration over args
        if isinstance(args, dict):
            iterator = args.items()
        else:
            # treat as list/tuple of arguments
            iterator = enumerate(args)

        for name, spec in iterator:
            # Extract value and maximum length
            if isinstance(spec, (list, tuple)) and len(spec) >= 2:
                value, max_len = spec[0], spec[1]
            elif isinstance(spec, dict):
                if 'value' not in spec:
                    raise TypeError(f"Argument spec for '{name}' is missing the 'value' key.")
                value = spec['value']
                max_len = spec.get('max_len', spec.get('max_length'))
                if max_len is None:
                    raise TypeError(f"Argument spec for '{name}' is missing a length specification ('max_len' or 'max_length').")
            else:
                raise TypeError(
                    f"Unsupported argument specification type for '{name}': {type(spec).__name__}. "
                    "Expected a (value, max_len) tuple/list or a dict with 'value' and 'max_len'/'max_length'."
                )

            # Validate that max_len is numeric
            if not isinstance(max_len, (int, float)):
                try:
                    max_len = int(max_len)
                except Exception as exc:
                    raise TypeError(
                        f"Maximum length for argument '{name}' must be an integer, got {max_len} ({type(max_len).__name__})."
                    ) from exc

            # Determine the length of the value if possible
            try:
                val_length = len(value)
            except Exception:
                # If we cannot determine length, skip validation for this item
                continue

            if val_length > max_len:
                raise ValueError(
