def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Ensure spec_option is a dictionary
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # Import argparse locally to keep namespace clean
    import argparse

    # Determine the conversion function based on spec_option['type']
    typ = spec_option.get('type', 'str')

    if typ == 'int':
        conv = int
    elif typ == 'float':
        conv = float
    elif typ == 'bool':
        def conv(v):
            if isinstance(v, bool):
                return v
            if isinstance(v, str):
                blist_true = {'true', '1', 'yes', 'y', 'on'}
                blist_false = {'false', '0', 'no', 'n', 'off'}
                v_low = v.lower()
                if v_low in blist_true:
                    return True
                if v_low in blist_false:
                    return False
            raise ValueError(f"Invalid boolean value: {v}")
    else:
        conv = str

    choices = spec_option.get('choices')
    if choices is not None:
        # Ensure choices are a list or tuple
        if not isinstance(choices, (list, tuple, set)):
            raise TypeError("choices must be a list, tuple, or set")

    def _type_func(value):
        try:
            val = conv(value)
        except Exception as exc:
            raise argparse.ArgumentTypeError(
                f"Invalid value for {option_name!r}: {exc}"
            ) from exc
        if choices is not None and val not in choices:
            raise argparse.ArgumentTypeError(
                f"Value {val!r} for {option_name!r} must be one of {list(choices)}"
            )
        return val

