def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    try:
        # Convert various possible inputs to a dictionary
        if args is None:
            return {}, {}
        if isinstance(args, dict):
            args_dict = dict(args)
        else:
            args_dict = {}
            # Accept lists of tuples, lists of "key=value" strings, or
            # iterables of key-value pairs
            for item in args:
                if isinstance(item, (tuple, list)) and len(item) == 2:
                    key, val = item
                    args_dict[key] = val
                elif isinstance(item, str) and '=' in item:
                    key, val = item.split('=', 1)
                    args_dict[key.strip()] = val.strip()
                elif hasattr(item, '__iter__'):
                    # Skip elaborate iterables that we cannot interpret
                    continue
        # Determine control keys.
        # Prefer an explicit attribute if defined
        control_keys = set()
        if hasattr(self, 'CONTROL_KEYS'):
            control_keys.update(self.CONTROL_KEYS)
        # Add heuristics for keys that are clearly used for controlling IR:
        #   keys that start with 'control_' or '_', or end with '_control'
        heuristics = {k for k in args_dict
                      if k.startswith('control_')
                      or k.startswith('_')
                      or k.endswith('_control')}
        control_keys.update(heuristics)

        # Split the dictionary
        control_args = {k: v for k, v in args_dict.items() if k in control_keys}
        nested_args = {k: v for k, v in args_dict.items() if k not in control_keys}
        return control_args, nested_args
    except Exception as exc:   # pragma: no cover
        # In case of unexpected input, return empty dicts and log the issue
        return {}, {}

