def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os

    # Normalize command line arguments
    if cli_args is None:
        cli_args = []
    elif isinstance(cli_args, str):
        # Split a single string into a list
        cli_args = cli_args.split()
    else:
        # Filter out any None values
        cli_args = [arg for arg in cli_args if arg is not None]

    # Ensure vars_dict is a dictionary
    try:
        if vars_dict is None:
            vars_dict = {}
        elif not isinstance(vars_dict, dict):
            vars_dict = dict(vars_dict)
    except Exception:
        vars_dict = {}

    # Build the base command
    cmd = ["ansible-playbook"] + cli_args

    # Append extra-vars if not already provided
    if vars_dict:
        # If the user already supplied '-e' or '--extra-vars', we skip adding another one.
        if not any(arg in ("-e", "--extra-vars") for arg in cli_args):
            cmd += ["--extra-vars", json.dumps(vars_dict)]

    # Determine working directory from the workspace, if available
    cwd = None
    for attr in ("path", "folder", "workspace_path", "cwd"):
        if hasattr(ir_workspace, attr):
            cwd = getattr(ir_workspace, attr)
            break

    # Prepare environment variables
    env = os.environ.copy()
    # Plugin might provide additional environment variables; if such an interface exists,
    # we incorporate them here.
    if hasattr(ir_plugin, "get_environment") and callable(ir_plugin.get_environment):
        try:
            env_updates = ir_plugin.get_environment()
            if isinstance(env_updates, dict):
                env.update(env_updates)
        except Exception:
            pass

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )
        return {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
        }
    except (OSError, FileNotFoundError) as e:
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Command execution failed: {e}",
        }
    except Exception as e:
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": str(e),
        }

