    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path

    try:
        plugin_path = Path(plugin_dir)
    except Exception:
        return {}

    spec_file = None
    for filename in ["plugin.yaml", "plugin.yml", "plugin.json"]:
        candidate = plugin_path / filename
        if candidate.is_file():
            spec_file = candidate
            break

    if not spec_file:
        return {}

    try:
        with spec_file.open("r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return {}

    data = None
    try:
        if spec_file.suffix in [".yaml", ".yml"]:
            import yaml  # type: ignore
            data = yaml.safe_load(text)
        else:
            import json
            data = json.loads(text)
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    def _flatten(d, parent_key=""):
        result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{k}" if not parent_key else f"{parent_key}.{k}"
            if isinstance(v, dict):
                result.update(_flatten(v, new_key))
            else:
                result[new_key] = v
        return result

    return _flatten(data)

