def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        raise ValueError("root cannot be empty")

    # If path exactly equals root, return empty string
    if path == root:
        return ""

    # If root ends with a separator, use it directly
    if root.endswith("/") or root.endswith("\\"):
        if path.startswith(root):
            return path[len(root):]
        else:
            raise ValueError(f"Path '{path}' does not start with root '{root}'")

    # For roots without a trailing separator
    # First try exact match with a separator following root
    sep_index = len(root)
    if len(path) > sep_index and path.startswith(root) and (path[sep_index] == "/" or path[sep_index] == "\\"):
        return path[sep_index + 1:]

    # If path starts with root but with no separator (e.g., root='/', root=''?), then no strip
    raise ValueError(f"Path '{path}' does not start with root '{root}'")

