def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    # Normalize potential trailing separators for root
    # We'll treat both forward and backward slashes as path separators.
    def is_separator(ch):
        return ch in ('/', '\\')

    # Ensure root is not empty to avoid accidental removal of all paths
    if root == "":
        raise ValueError("Root cannot be an empty string")

    # Check prefix match
    if not path.startswith(root):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # After root, the next character must be a separator or nothing (exact match)
    if len(path) == len(root):
        return ""  # root is exactly the path

    next_char = path[len(root)]
    if not is_separator(next_char):
        raise ValueError(f"Root '{root}' is not a directory prefix of path '{path}'")

    # Strip root and leading separators from the remaining part
    stripped = path[len(root):]
    # Remove any leading separators
    stripped = stripped.lstrip('/\\')
    return stripped

